const payload = $input.first().json.data || $input.first().json;

const area = Number(payload.builtUpAreaSqFt) || 1200;
const pkg = (payload.preferredPackage || 'premium').toLowerCase();
const hasPlot = payload.hasPlot !== false;
const timeline = (payload.startingTimeline || '').toLowerCase();

// 1. BOQ & Material Estimator Engine
// Rule of Thumb engineering ratios per sq.ft built-up area in South India:
// Cement: ~0.4 bags/sq.ft
// Steel (Fe550D): ~3.8 kg/sq.ft
// Coarse Aggregate (Jelly): ~0.65 cu.ft/sq.ft
// M-Sand: ~1.2 cu.ft/sq.ft
// Bricks / Blocks: ~18 bricks/sq.ft

const cementBags = Math.round(area * 0.42);
const steelTonnes = ((area * 3.8) / 1000).toFixed(2);
const brickCount = Math.round(area * 18);

// Pricing calculation
let ratePerSqFt = 2350;
let pkgLabel = 'Premium Luxury (₹2,350/sq.ft)';
if (pkg.includes('standard') || pkg.includes('budget')) {
  ratePerSqFt = 1950;
  pkgLabel = 'Standard Package (₹1,950/sq.ft)';
} else if (pkg.includes('luxury') || pkg.includes('elite')) {
  ratePerSqFt = 2850;
  pkgLabel = 'Elite Royal Villa (₹2,850/sq.ft)';
}

const minCostLakhs = ((area * (ratePerSqFt - 100)) / 100000).toFixed(2);
const maxCostLakhs = ((area * ratePerSqFt) / 100000).toFixed(2);

// Lead Qualification Scoring
let leadScore = 'WARM';
let priorityRank = 'P2 - Normal Followup (Within 4 hrs)';
if (hasPlot && (timeline.includes('immediate') || timeline.includes('1 month') || timeline.includes('this month') || timeline.includes('next month'))) {
  leadScore = 'HOT 🔥';
  priorityRank = 'P1 - VIP Urgent (Call within 15 mins)';
} else if (!hasPlot) {
  leadScore = 'COLD / EXPLORING';
  priorityRank = 'P3 - Nurture with Floor Plans';
}

// WhatsApp Alert message for the Builder (Er. Dhilip Kumar)
const builderAlertText = `🏗️ *NEW HOUSE CONSTRUCTION ENQUIRY!*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `👤 *Client:* ${payload.customerName || 'Prospect'}\n` +
  `📱 *Phone:* ${payload.customerPhone || 'Not provided'}\n` +
  `📍 *Site Location:* ${payload.siteLocation || 'Madurai'}\n` +
  `📐 *Plot Status:* ${hasPlot ? 'Owns Plot (' + (payload.plotDimensions || 'Standard') + ')' : 'Looking for Plot'}\n` +
  `🏠 *Planned Area:* ${area} Sq.Ft (${payload.floors || 'G+1'}, ${payload.bedrooms || '3 BHK'})\n` +
  `📦 *Selected Package:* ${pkgLabel}\n` +
  `💰 *Budget Range:* ₹${minCostLakhs}L – ₹${maxCostLakhs}L\n` +
  `⏳ *Start Timeline:* ${payload.startingTimeline || 'Next 1-2 months'}\n` +
  `📝 *Special Notes:* ${payload.specialRequirements || 'None'}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📊 *Lead Priority:* ${leadScore} (${priorityRank})\n` +
  `🧱 *BOQ Preview:* ~${cementBags} Cement bags | ${steelTonnes} Tonnes TMT Steel | ~${brickCount} Bricks\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📞 *Quick Call:* https://wa.me/${(payload.customerPhone || '').replace(/[^0-9]/g, '')}`;

// WhatsApp Confirmation message for Homeowner
const clientReplyText = `வணக்கம் ${payload.customerName || 'சார்'}! 🏡✨\n\n` +
  `Thank you for reaching out to *Danam Holdings Civil Engineering & Turnkey EPC*.\n\n` +
  `📋 *Your Project Summary (ID: #${payload.enquiryId || 'NEW'}):*\n` +
  `• *Site:* ${payload.siteLocation || 'Madurai'}\n` +
  `• *Built-up Area:* ${area} Sq.Ft (${payload.floors || 'G+1'})\n` +
  `• *Package:* ${pkgLabel}\n` +
  `• *Estimated Cost:* ₹${minCostLakhs} – ₹${maxCostLakhs} Lakhs\n\n` +
  `Our Chief Engineer *Er. Dhilip Kumar* will review your plot dimensions and reach out to arrange a *Free Site & Soil Inspection*.\n\n` +
  `Meanwhile, explore our completed projects and 360° virtual tours: https://danamholdings.com`;

return [{
  json: {
    ...payload,
    builtUpAreaSqFt: area,
    packageLabel: pkgLabel,
    ratePerSqFt,
    estimatedMinLakhs: minCostLakhs,
    estimatedMaxLakhs: maxCostLakhs,
    leadScore,
    priorityRank,
    cementBagsEstimated: cementBags,
    steelTonnesEstimated: steelTonnes,
    brickCountEstimated: brickCount,
    builderAlertMessage: builderAlertText,
    clientReplyMessage: clientReplyText,
    processedAt: new Date().toISOString()
  }
}];
